class Solution {
    public void nextPermutation(int[] nums) {
        int n = nums.length;
        int pivot = n - 2;

        while (pivot >= 0 && nums[pivot] >= nums[pivot + 1]) {
            pivot--;
        }

        if (pivot >= 0) {
            int successor = n - 1;
            while (nums[successor] <= nums[pivot]) {
                successor--;
            }
            swap(nums, pivot, successor);
        }

        reverse(nums, pivot + 1, n - 1);
    }

    private void reverse(int[] nums, int left, int right) {
        while (left < right) {
            swap(nums, left++, right--);
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

class Solution {
    public void nextPermutation(int[] nums) {
        int n = nums.length;
        int pivot = n - 2;

        while (pivot >= 0 && nums[pivot] >= nums[pivot + 1]) {
            pivot--;
        }

        if (pivot >= 0) {
            int successor = rightmostGreaterInDescendingSuffix(nums, pivot + 1, n - 1, nums[pivot]);
            swap(nums, pivot, successor);
        }

        reverse(nums, pivot + 1, n - 1);
    }

    private int rightmostGreaterInDescendingSuffix(int[] nums, int left, int right, int target) {
        int answer = right;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] > target) {
                answer = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return answer;
    }

    private void reverse(int[] nums, int left, int right) {
        while (left < right) {
            swap(nums, left++, right--);
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

class Solution {
    public void nextPermutation(int[] nums) {
        int n = nums.length;
        int pivot = n - 2;

        while (pivot >= 0 && nums[pivot] >= nums[pivot + 1]) {
            pivot--;
        }

        if (pivot >= 0) {
            int successor = pivot + 1;
            for (int i = pivot + 1; i < n; i++) {
                if (nums[i] > nums[pivot] && nums[i] <= nums[successor]) {
                    successor = i;
                }
            }
            swap(nums, pivot, successor);
            selectionSort(nums, pivot + 1, n - 1);
        } else {
            selectionSort(nums, 0, n - 1);
        }
    }

    private void selectionSort(int[] nums, int left, int right) {
        for (int i = left; i <= right; i++) {
            int minIndex = i;
            for (int j = i + 1; j <= right; j++) {
                if (nums[j] < nums[minIndex]) {
                    minIndex = j;
                }
            }
            swap(nums, i, minIndex);
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}
